### cURL

```bash
# Health check
curl http://localhost:8000/health

# Search query
curl -X POST "http://localhost:8000/search" \
  -H "Content-Type: application/json" \
  -d '{
    "query": "What is continuous integration?",
    "max_results": 3
  }'

# Index content (used by deployment workflows)
curl -X POST "http://localhost:8000/api/rag/v1/index" \
  -H "Content-Type: application/json" \
  -d '{
    "files": [
      {
        "path": "README.md",
        "content": "# Enterprise Architecture\n\nWelcome to...",
        "metadata": {
          "size_bytes": 1234,
          "mtime": "2026-02-20T10:30:00Z"
        }
      }
    ],
    "total_files": 1,
    "environment": "dev"
  }'
```
